CREATE OR ALTER PROCEDURE [dbo].[uspActualCost_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @ProductionBatchId UNIQUEIDENTIFIER = NULL
	, @ProductionOrderId UNIQUEIDENTIFIER = NULL
	, @MaterialCost DECIMAL(18,2) = NULL
	, @LaborCost DECIMAL(18,2) = NULL
	, @OverheadCost DECIMAL(18,2) = NULL
	, @OtherCost DECIMAL(18,2) = NULL
	, @TotalCost DECIMAL(18,2) = NULL
	, @CurrencyCode NVARCHAR(MAX) = NULL
	, @CalculatedAt DATETIME2 = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[ProductionBatchId]
			, j1.[BatchNo] AS [ProductionBatchName]
			, t.[MaterialCost]
			, t.[LaborCost]
			, t.[OverheadCost]
			, t.[WasteCost]
			, t.[TotalCost]
			, t.[ProductionOrderId]
			, j2.[ProductionOrderNo] AS [ProductionOrderName]
			, t.[OtherCost]
			, t.[CurrencyCode]
			, t.[CalculatedAt]
			, t.[CreatedDate]
		FROM [dbo].[ActualCost] AS t
		LEFT JOIN [dbo].[ProductionBatche] AS j1 ON j1.[Id] = t.[ProductionBatchId]
		LEFT JOIN [dbo].[ProductionOrder] AS j2 ON j2.[Id] = t.[ProductionOrderId]
		WHERE (ISNULL(@SearchText, '') = '' OR t.[CurrencyCode] LIKE CONCAT('%', @SearchText, '%'))
			AND (@ProductionBatchId IS NULL OR t.[ProductionBatchId] = @ProductionBatchId)
			AND (@ProductionOrderId IS NULL OR t.[ProductionOrderId] = @ProductionOrderId)
			AND (@MaterialCost IS NULL OR t.[MaterialCost] = @MaterialCost)
			AND (@LaborCost IS NULL OR t.[LaborCost] = @LaborCost)
			AND (@OverheadCost IS NULL OR t.[OverheadCost] = @OverheadCost)
			AND (@OtherCost IS NULL OR t.[OtherCost] = @OtherCost)
			AND (@TotalCost IS NULL OR t.[TotalCost] = @TotalCost)
			AND (ISNULL(@CurrencyCode, '') = '' OR t.[CurrencyCode] LIKE CONCAT('%', @CurrencyCode, '%'))
			AND (@CalculatedAt IS NULL OR t.[CalculatedAt] = @CalculatedAt)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'productionBatchId' THEN r.[ProductionBatchId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'productionBatchId' THEN r.[ProductionBatchId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'productionBatchName' THEN r.[ProductionBatchName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'productionBatchName' THEN r.[ProductionBatchName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'materialCost' THEN r.[MaterialCost] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'materialCost' THEN r.[MaterialCost] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'laborCost' THEN r.[LaborCost] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'laborCost' THEN r.[LaborCost] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'overheadCost' THEN r.[OverheadCost] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'overheadCost' THEN r.[OverheadCost] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'wasteCost' THEN r.[WasteCost] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'wasteCost' THEN r.[WasteCost] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'totalCost' THEN r.[TotalCost] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'totalCost' THEN r.[TotalCost] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'productionOrderId' THEN r.[ProductionOrderId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'productionOrderId' THEN r.[ProductionOrderId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'productionOrderName' THEN r.[ProductionOrderName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'productionOrderName' THEN r.[ProductionOrderName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'otherCost' THEN r.[OtherCost] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'otherCost' THEN r.[OtherCost] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'currencyCode' THEN r.[CurrencyCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'currencyCode' THEN r.[CurrencyCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'calculatedAt' THEN r.[CalculatedAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'calculatedAt' THEN r.[CalculatedAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
